import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        int[] ea = new int[m], eb = new int[m], deg = new int[n + 1];
        for (int i = 0; i < m; i++) {
            ea[i] = nextInt();
            eb[i] = nextInt();
            deg[ea[i] + 1]++;
            deg[eb[i] + 1]++;
        }
        // Compressed adjacency lists: neighbors of u are adj[start[u] .. start[u + 1]).
        int[] start = new int[n + 1];
        for (int i = 0; i < n; i++) start[i + 1] = start[i] + deg[i + 1];
        int[] fill = Arrays.copyOf(start, n), adj = new int[2 * m];
        for (int i = 0; i < m; i++) {
            adj[fill[ea[i]]++] = eb[i];
            adj[fill[eb[i]]++] = ea[i];
        }
        int[] count = new int[n], friendOf = new int[n], touched = new int[n];
        Arrays.fill(friendOf, -1);
        StringBuilder sb = new StringBuilder();
        for (int u = 0; u < n; u++) {
            for (int k = start[u]; k < start[u + 1]; k++) friendOf[adj[k]] = u;
            int t = 0;
            // Count two-hop paths u - v - w to non-friends w.
            for (int k = start[u]; k < start[u + 1]; k++) {
                int v = adj[k];
                for (int l = start[v]; l < start[v + 1]; l++) {
                    int w = adj[l];
                    if (w != u && friendOf[w] != u && count[w]++ == 0) touched[t++] = w;
                }
            }
            int best = -1;
            for (int i = 0; i < t; i++) {
                int w = touched[i];
                if (best < 0 || count[w] > count[best] || (count[w] == count[best] && w < best)) best = w;
            }
            for (int i = 0; i < t; i++) count[touched[i]] = 0;
            if (best < 0) {
                // No positive candidate: the smallest ID that is neither u nor a friend.
                best = 0;
                while (best < n && (best == u || friendOf[best] == u)) best++;
                if (best == n) best = -1;
            }
            if (u > 0) sb.append(' ');
            sb.append(best);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	adj := make([][]int, n)
	for i := 0; i < m; i++ {
		a, b := nextInt(), nextInt()
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
	}
	count := make([]int, n)
	friendOf := make([]int, n)
	for i := range friendOf {
		friendOf[i] = -1
	}
	touched := []int{}
	out := make([]string, n)
	for u := 0; u < n; u++ {
		for _, v := range adj[u] {
			friendOf[v] = u
		}
		touched = touched[:0]
		// Count two-hop paths u - v - w to non-friends w.
		for _, v := range adj[u] {
			for _, w := range adj[v] {
				if w != u && friendOf[w] != u {
					if count[w] == 0 {
						touched = append(touched, w)
					}
					count[w]++
				}
			}
		}
		best := -1
		for _, w := range touched {
			if best < 0 || count[w] > count[best] || (count[w] == count[best] && w < best) {
				best = w
			}
		}
		for _, w := range touched {
			count[w] = 0
		}
		if best < 0 {
			// No positive candidate: the smallest ID that is neither u nor a friend.
			best = 0
			for best < n && (best == u || friendOf[best] == u) {
				best++
			}
			if best == n {
				best = -1
			}
		}
		out[u] = strconv.Itoa(best)
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fmt.Fprintln(w, strings.Join(out, " "))
}
